import {ToolRegistry} from './registry.js';

describe('ToolRegistry unit', () => {
  it('throws at register time naming the tool when a static inputSchema cannot be compiled (specs/hal-engine-tool-input-validation/spec.md#L18)', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'not-a-json-schema-type' as unknown as 'string'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_weather/);
  });

  it('validates input in ToolRegistry.execute before calling the executor (specs/hal-engine-tool-input-validation/spec.md#L8)', async () => {
    const registry = new ToolRegistry();
    let called = false;
    registry.register(
      {
        name: 'test_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {foo: {type: 'string'}},
          required: ['foo'],
        },
      },
      async () => {
        called = true;
        return 'ok';
      }
    );

    const response = await registry.execute('test_tool', {});
    expect(response.result).toMatch(/foo/);
    expect(response.result).toMatch(/required/i);
    expect(called).toBe(false);
  });
});

import Ajv from 'ajv';
import type {ValidateFunction, Options} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

const ajvOptions: Options = {
  strict: false,
  validateFormats: false,
};
const ajv = new Ajv(ajvOptions);

export interface ToolResponse {
...
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }

    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = tool.staticValidator ?? this.compileSchema(name, definition.inputSchema);

    if (!validator(input)) {
      const errors = validator.errors || [];
      const result = errors
        .map(e => {
          const field = e.instancePath ? e.instancePath.replace(/^\//, '').replace(/\//g, '.') : e.params.missingProperty;
          return `${field ? field + ': ' : ''}${e.message}`;
        })
        .join(', ');

      log.warn('tool', 'invalid input', {name, errors: result});
      return {result: `Invalid input: ${result}`};
    }

    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

